-- JOBSEARCH-PROFILE-1 (2026-10-28, charter pillar reach; owner feedback in chat 2026-10-28): the search is the owner's, not a fixed AI-lab filter. Yes/no preference survey, role families drawn from
-- the whole record, location gates from the owner answers, likes and dislikes that teach the search, rejected matches that stay hidden, and a "check a job" analysis. The worker also creates these two
-- tables on first use (CREATE TABLE IF NOT EXISTS), so deploy order does not matter.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DROP TABLE IF EXISTS jobsearch_prefs; DROP TABLE IF EXISTS jobsearch_feedback; UPDATE agent_issues SET status = 'closed' WHERE title LIKE 'JOBSEARCH-NL-PUBLIC-SECTOR-1:%'; UPDATE roadmap_implementation SET status = 'retired' WHERE item IN ('JS-10', 'JS-11') AND source = 'jobsearch-2026';
CREATE TABLE IF NOT EXISTS jobsearch_prefs (k TEXT PRIMARY KEY, v TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS jobsearch_feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL, title TEXT, company TEXT, verdict TEXT NOT NULL, source TEXT);

INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'JS-10', 'jobsearch-2026', 'Search profile: yes/no survey, role families from the whole record, owner-driven location gates, learning from likes and dislikes, check-a-job analysis', 'worker', 'qnfo-jobsearch', 'built', 'qnfo-jobsearch 1.3.0; owner feedback 2026-10-28 (US on-site listed for an Amsterdam resident, narrow AI-only titles, rejected matches reappearing)' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'JS-10' AND source = 'jobsearch-2026');
INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'JS-11', 'jobsearch-2026', 'Dutch government, universities and consultancies: employers with no open feed', 'worker', 'qnfo-jobsearch', 'planned', 'agent_issues JOBSEARCH-NL-PUBLIC-SECTOR-1; probed 2026-10-28: werkenvoornederland.nl, academictransfer.com, euraxess, jobs.ac.uk expose no open API or RSS' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'JS-11' AND source = 'jobsearch-2026');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'JOBSEARCH-NL-PUBLIC-SECTOR-1: the work the owner knows best (policy, transport and planning, public-sector research) is posted where qnfo-jobsearch has no feed',
 'Charter pillar: reach. Owner feedback 2026-10-28: the matches were too narrow. After 1.3.0 the feeds cover tech employers, The Muse, Jobicy, Remotive and Arbeitnow (56 feeds, about 9,900 postings), and the Amsterdam matches are mostly product and data roles. The owner record is public-policy research, transport and travel-demand modelling, planning, GIS, federal research and contract management, housing and ageing policy. Those employers (Dutch ministries and municipalities, EU institutions, universities and research institutes, consultancies, think tanks) post on werkenvoornederland.nl, academictransfer.com, euraxess and their own career pages. Probed 2026-10-28: none of werkenvoornederland.nl RSS, academictransfer.com API or RSS, euraxess RSS, jobs.ac.uk RSS answers as an open feed (404 or HTML). Doer: qnfo-code-orchestrator. Lever: (1) read each site robots.txt and terms first and record the answer in the issue; a site that forbids automated reading is out. (2) For a site that allows it, add a reader to FETCHERS in qnfo-jobsearch/worker.js that fetches listing pages and reads each posting through its schema.org JobPosting JSON-LD (jsonLdPosting already exists), at most one request per second and 200 postings per run, with its own feed key so failures show in /api/ops. (3) Add the sources to BOARDS only when the reader returns postings in the offline test. Do not scrape LinkedIn or Indeed (LinkedIn User Agreement 8.2). Definition of done: at least one Dutch public-sector or research source returns postings for 3 runs in a row, GET /api/runs lists its feed, and the version line carries JOBSEARCH-NL-PUBLIC-SECTOR-1.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-jobsearch/worker.js' || char(10) ||
 'code-anchor: async arbeitnow() {' || char(10) ||
 'code-probe: {"paths": ["qnfo-jobsearch/worker.js"], "contains": "JOBSEARCH-NL-PUBLIC-SECTOR-1"}',
 'session', 'reliability', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'JOBSEARCH-NL-PUBLIC-SECTOR-1:%' AND status = 'open');
